/* An 8-bit CRC that shifts towards the most significant bit. Its register is exactly as wide
 * as one input byte, so the byte is XORed into the whole register and no part of the old
 * register is left over to be shifted: the table entry is the new register. */
static uint8_t crc8_table_update(const uint8_t *table, uint8_t crc, const uint8_t *data, size_t len)
{
    uint8_t reg = crc;

    for (size_t i = 0U; i < len; i++) {
        reg = table[(uint8_t)(reg ^ data[i])];
    }

    return reg;
}

uint8_t crc8_j1850_update(uint8_t crc, const uint8_t *data, size_t len)
{
    return crc8_table_update(s_crc8_j1850_table, crc, data, len);
}

uint8_t crc8_h2f_update(uint8_t crc, const uint8_t *data, size_t len)
{
    return crc8_table_update(s_crc8_h2f_table, crc, data, len);
}

#define CRC15_CAN_POLY     0x4599U /* x^14 + x^10 + x^8 + x^7 + x^4 + x^3 + 1; x^15 is implied */
#define CRC15_CAN_MSB      0x4000U /* CRC_RG(14), the bit that leaves the register on a shift */
#define CRC15_CAN_REGISTER 0x7FFFU /* CRC_RG(14:0) */

uint16_t crc15_can_update_bit(uint16_t crc, uint8_t bit)
{
    /* This is the shift register of the Bosch CAN Specification 2.0, section 3.2.1,
     * "CRC SEQUENCE", statement for statement:
     *
     *     CRCNXT = NXTBIT EXOR CRC_RG(14);
     *     CRC_RG(14:1) = CRC_RG(13:0);
     *     CRC_RG(0) = 0;
     *     IF CRCNXT THEN CRC_RG(14:0) = CRC_RG(14:0) EXOR (4599hex);
     *
     * The header asks for a bit of 0 or 1. Any other non-zero value is taken as 1, so that a
     * caller who passes a masked but unshifted bit (byte & 0x80) gets the level it meant.
     * Bit 15 of `crc` is not part of the register; the shift drops it. */
    const bool nxtbit = (bit != 0U);
    const bool msb = ((crc & CRC15_CAN_MSB) != 0U);
    uint32_t reg = ((uint32_t)crc << 1U) & CRC15_CAN_REGISTER;

    if (nxtbit != msb) {
        reg ^= CRC15_CAN_POLY;
    }

    return (uint16_t)reg;
}

uint16_t crc15_can_update(uint16_t crc, const uint8_t *data, size_t len)
{
    uint16_t reg = crc;

    for (size_t i = 0U; i < len; i++) {
        /* Most significant bit first, the order in which CAN transmits a byte. */
        for (uint32_t left = 8U; left > 0U; left--) {
            const uint8_t bit = (uint8_t)(((uint32_t)data[i] >> (left - 1U)) & 1U);

            reg = crc15_can_update_bit(reg, bit);
        }
    }

    return reg;
}

uint32_t crc32_update(uint32_t crc, const uint8_t *data, size_t len)
{
    uint32_t reg = crc;

    for (size_t i = 0U; i < len; i++) {
        /* The register shifts right, so the byte meets its low eight bits. The other 24 bits
         * are not touched by the byte: they only move down by eight places. */
        reg = s_crc32_table[(reg ^ data[i]) & 0xFFU] ^ (reg >> 8U);
    }

    return reg;
}

uint32_t crc32_compute(const uint8_t *data, size_t len)
{
    return crc32_update(CRC32_INIT, data, len) ^ CRC32_XOROUT;
}
